package com.fooddelivery.controller;
import com.fooddelivery.dto.AuthDtos.*; import com.fooddelivery.model.*; import com.fooddelivery.repository.UserRepository; import com.fooddelivery.security.JwtService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.authentication.*; import org.springframework.security.core.userdetails.User; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { final UserRepository users; final PasswordEncoder encoder; final AuthenticationManager auth; final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder e,AuthenticationManager a,JwtService j){users=u;encoder=e;auth=a;jwt=j;} @PostMapping("/register") public AuthResponse register(@Valid @RequestBody RegisterRequest r){if(users.findByEmail(r.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");var u=new com.fooddelivery.model.User();u.setEmail(r.email());u.setPassword(encoder.encode(r.password()));u.setFullName(r.fullName());u.setAddress(r.address());u.setPhoneNumber(r.phoneNumber());u.setRole(UserRole.CUSTOMER);users.save(u);return token(u);} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){auth.authenticate(new UsernamePasswordAuthenticationToken(r.email(),r.password()));return token(users.findByEmail(r.email()).orElseThrow());} AuthResponse token(com.fooddelivery.model.User u){var p=User.withUsername(u.getEmail()).password(u.getPassword()).roles(u.getRole().name()).build();return new AuthResponse(jwt.generate(p),u.getEmail(),u.getFullName(),u.getRole().name());} }